  ('c12ec735-4185-5b9c-b51f-1c2f0a2de282', '0d2ef365-02ef-5e93-9deb-2a0f24696115', '3258bb65-798e-5c07-8b64-08f7cc782f7b', 'Allied Health Sciences::Nursing Sciences', 'D026', 'functional', 'scorer', 'strong', 4, '[{"title":"Community/Public Health Nursing I","mapping_title":null,"code":"NSC 303","course_identity":"NSC 303::Community/Public Health Nursing I","matched_anchors":["public health"]},{"title":"Community/Public Health Nursing II","mapping_title":null,"code":"NSC 302","course_identity":"NSC 302::Community/Public Health Nursing II","matched_anchors":["public health"]},{"title":"Community/Public Health Nursing III","mapping_title":null,"code":"NSC 410","course_identity":"NSC 410::Community/Public Health Nursing III","matched_anchors":["public health"]},{"title":"Community/Public Health Nursing Practicum III","mapping_title":null,"code":"NSC 501","course_identity":"NSC 501::Community/Public Health Nursing Practicum III","matched_anchors":["public health"]}]'::jsonb, 0, '[]'::jsonb, false, false, '{"ccmas_source_file":"allied_health.json","ccmas_code":"NSC","qualification":null,"duration_years":5,"domain_name":"Public Health","domain_definition":"Public health protects the health of whole communities rather than one patient at a time. Inspectors enforce food, workplace and community health standards, officers and physicians coordinate emergency responses and prevention work, and scientists track diseases and analyse health statistics. Government agencies, hospitals and international health organisations are typical employers.","audit_source":"programme_domain_evidence_2026-08-17","source_flagged_courses":[],"programme_source_flags":[],"adjacent_evidence_gate":null}'::jsonb),
  ('7b070f89-0b8b-5458-8781-aa04775e2754', '0d2ef365-02ef-5e93-9deb-2a0f24696115', '3378be05-efd0-5c2d-bc2d-bb973c0a6d1c', 'Allied Health Sciences::Nursing Sciences', 'D145', 'functional', 'scorer', 'strong', 3, '[{"title":"Developmental Psychology","mapping_title":null,"code":"NSC 203","course_identity":"NSC 203::Developmental Psychology","matched_anchors":["psychology"]},{"title":"Research Methodology","mapping_title":null,"code":"NSC 409","course_identity":"NSC 409::Research Methodology","matched_anchors":["research design"]},{"title":"Community/Public Health Nursing Practicum III","mapping_title":null,"code":"NSC 501","course_identity":"NSC 501::Community/Public Health Nursing Practicum III","matched_anchors":["consultation"]}]'::jsonb, 0, '[]'::jsonb, false, false, '{"ccmas_source_file":"allied_health.json","ccmas_code":"NSC","qualification":null,"duration_years":5,"domain_name":"Neuroscience, Cognitive Science","domain_definition":"Neuroscience and cognitive science investigate the brain, thought and behaviour. One side of the field involves scientists studying how the brain and mind work; the other involves psychologists and psychotherapists who assess and treat mental and behavioural health. They work in hospitals, clinics, schools and universities.","audit_source":"programme_domain_evidence_2026-08-17","source_flagged_courses":[],"programme_source_flags":[],"adjacent_evidence_gate":null}'::jsonb),
  ('9d7644a0-1752-5430-9355-6eb41fd3ded2', '0d2ef365-02ef-5e93-9deb-2a0f24696115', 'b617cc0c-dacd-58a1-92e7-a84f18329168', 'Allied Health Sciences::Nursing Sciences', 'D165', 'functional', 'scorer', 'strong', 6, '[{"title":"Foundations of Nursing II","mapping_title":null,"code":"NSC 202","course_identity":"NSC 202::Foundations of Nursing II","matched_anchors":["nutrition"]},{"title":"Human Nutrition","mapping_title":null,"code":"NSC 307","course_identity":"NSC 307::Human Nutrition","matched_anchors":["nutrition"]},{"title":"Community/Public Health Nursing II","mapping_title":null,"code":"NSC 302","course_identity":"NSC 302::Community/Public Health Nursing II","matched_anchors":["health promotion"]},{"title":"Mental Health and Psychiatric Nursing I","mapping_title":null,"code":"NSC 314","course_identity":"NSC 314::Mental Health and Psychiatric Nursing I","matched_anchors":["health promotion"]},{"title":"Maternal and Child Health Nursing Practicum 1","mapping_title":null,"code":"NSC 404","course_identity":"NSC 404::Maternal and Child Health Nursing Practicum 1","matched_anchors":["nutrition"]},{"title":"Community/Public Health Nursing Practicum III","mapping_title":null,"code":"NSC 501","course_identity":"NSC 501::Community/Public Health Nursing Practicum III","matched_anchors":["health promotion"]}]'::jsonb, 0, '[]'::jsonb, false, false, '{"ccmas_source_file":"allied_health.json","ccmas_code":"NSC","qualification":null,"duration_years":5,"domain_name":"Wellness Coaching, Lifestyle Medicine","domain_definition":"Wellness coaching and lifestyle medicine help people stay healthy through everyday habits. Dietitians and nutritionists advise on food, fitness instructors and pilates teachers lead exercise, and music and dance therapists use creative activities to support healing. Clinics, gyms, wellness centres and private practice are typical settings.","audit_source":"programme_domain_evidence_2026-08-17","source_flagged_courses":[],"programme_source_flags":[],"adjacent_evidence_gate":null}'::jsonb),
